    async fn dispatch(self, handler: &mut H) -> anyhow::Result<()> {
        match self {
            Self::ConfigOperationMode { mode } => handler.config_operation_mode(mode).await,
            Self::ConfigAutoFocus { state } => handler.config_auto_focus(state).await,
            Self::ConfigFocusLevel { level } => handler.config_focus_level(level).await,
            Self::CmdSetFocusByStep { steps } => handler.cmd_set_focus_by_step(steps).await,
            Self::ConfigDigitalZoom { enable } => handler.config_digital_zoom(enable).await,
            Self::ConfigZoomLevel { level } => handler.config_zoom_level(level).await,
            Self::CmdSetZoomByStep { steps } => handler.cmd_set_zoom_by_step(steps).await,
            Self::ConfigPredefinedZoomFov { predefined_level } => handler.config_predefined_zoom_fov(predefined_level).await,
            Self::CmdSetPredefinedZoomFovByStep { steps } => handler.cmd_set_predefined_zoom_fov_by_step(steps).await,
            Self::ConfigAutoBrightness { enable } => handler.config_auto_brightness(enable).await,
            Self::ConfigBrightnessLevel { level } => handler.config_brightness_level(level).await,
            Self::CmdSetBrightnessByStep { steps } => handler.cmd_set_brightness_by_step(steps).await,
            Self::ConfigAutoContrast { enable } => handler.config_auto_contrast(enable).await,
            Self::ConfigContrastLevel { level } => handler.config_contrast_level(level).await,
            Self::CmdSetContrastByStep { steps } => handler.cmd_set_contrast_by_step(steps).await,
            Self::ConfigHdrMode { mode } => handler.config_hdr_mode(mode).await,
            Self::ConfigPolarity { hot_is } => handler.config_polarity(hot_is).await,
            Self::ConfigEconomyMode { enable } => handler.config_economy_mode(enable).await,
            Self::ConfigCooler { enable } => handler.config_cooler(enable).await,
            Self::ConfigAutoGain { enable } => handler.config_auto_gain(enable).await,
            Self::ConfigGainLevel { level } => handler.config_gain_level(level).await,
            Self::CmdSetGainByStep { steps } => handler.cmd_set_gain_by_step(steps).await,
            Self::ConfigExposureTime { shutter_speed_per_sec } => handler.config_exposure_time(shutter_speed_per_sec).await,
            Self::ConfigAutoExposure { enable } => handler.config_auto_exposure(enable).await,
            Self::ConfigAperture { aperture } => handler.config_aperture(aperture).await,
            Self::CmdSetRegionOfInterest { rectangle } => handler.cmd_set_region_of_interest(rectangle).await,
            Self::CmdClearRegionOfInterest => handler.cmd_clear_region_of_interest().await,
            Self::ConfigExternalTriggerMode { enable } => handler.config_external_trigger_mode(enable).await,
            Self::ConfigGrabbing { enable } => handler.config_grabbing(enable).await,
            Self::CmdCalibrateNuc { is_calibrating } => handler.cmd_calibrate_nuc(is_calibrating).await,
            Self::ConfigAutoCalibrateNuc { is_active } => handler.config_auto_calibrate_nuc(is_active).await,
            Self::ConfigAlphaBlendingLevel { level } => handler.config_alpha_blending_level(level).await,
            Self::CmdSetFalseColour { enable, name } => handler.cmd_set_false_colour(enable, name).await,
            Self::ConfigInfraredDynamicMode { enable } => handler.config_infrared_dynamic_mode(enable).await,
            Self::ConfigSelectCameraPreset { name } => handler.config_select_camera_preset(name).await,
            Self::CmdStartFocusEngine { direction } => handler.cmd_start_focus_engine(direction).await,
            Self::CmdStopFocusEngine => handler.cmd_stop_focus_engine().await,
            Self::CmdStartZoomEngine { direction } => handler.cmd_start_zoom_engine(direction).await,
            Self::CmdStopZoomEngine => handler.cmd_stop_zoom_engine().await,
            Self::CmdFreezeImage => handler.cmd_freeze_image().await,
        }
    }
