/// Marker type for the service side of `M_Camera`.
#[derive(Debug, Clone, Copy)]
pub enum ServiceRole {}

impl crate::Role for ServiceRole {
    type Incoming = ServiceMessage;
    type Outgoing = ClientMessage;
    const NAME: &'static str = "M_Camera::Service";

    fn vtable() -> &'static onboardapi_sys::obapi_vtable {
        // SAFETY: the vtable is an immutable static defined by the C++ shim.
        unsafe { &*(&raw const onboardapi_sys::obapi_Camera_service_vtable) }
    }
}

/// `M_Camera::Service`: receives [`ServiceMessage`], sends [`ClientMessage`].
pub type Service = crate::Endpoint<ServiceRole>;

/// Typed senders, one per outgoing operation. They encode straight from borrowed data.
impl crate::Endpoint<ServiceRole> {
    /// Report with static camera settings.
    /// This should be provided at startup and in the event of degraded functionality,
    /// e.g. due to an internal failure.
    pub fn report_camera_settings(&self, settings: &CameraSettingsType) -> crate::Result<()> {
        let mut w = Writer::default();
        settings.encode(&mut w);
        self.send_raw(0, w.as_bytes())
    }

    /// Report with the current camera status.
    /// This will be continually updated every time a value is changed.
    pub fn report_camera_status(&self, status: &CameraStatusType, is_removed: bool) -> crate::Result<()> {
        let mut w = Writer::default();
        status.encode(&mut w);
        is_removed.encode(&mut w);
        self.send_raw(1, w.as_bytes())
    }

    /// Send safety code(s) of the current frame.
    pub fn event_safety_code(&self, safety_code_list: &SafetyCodeListType) -> crate::Result<()> {
        let mut w = Writer::default();
        safety_code_list.encode(&mut w);
        self.send_raw(2, w.as_bytes())
    }

}

